/*
 * A095342  Number of elements in n-th string generated by a Kolakoski(5,1)
 *          rule starting with a(1)=1.
 * https://oeis.org/A095342
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = a(n-1) + 2*a(n-2) - 2*(-1)^n, with a(1)=a(2)=1
 * Range:     u8 n <= 9, u16 n <= 17, u32 n <= 33, u64 n <= 65, u128 n <= 129,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Computes the n-th term of OEIS A095342. */

seq_t a(idx_t n)
{
    if (n < 1)
        return 0;              /* undefined for n < 1, return 0 */

    if (n == 1 || n == 2)
        return (seq_t)1;

    seq_t a_nm2 = (seq_t)1;    /* a(1) */
    seq_t a_nm1 = (seq_t)1;    /* a(2) */
    seq_t a_n = 0;

    for (idx_t k = 3; k <= n; ++k) {
        seq_t tmp = a_nm1 + (a_nm2 * 2);
        if ((k & 1) == 0)          /* k even: (-1)^k = 1  -> subtract 2 */
            a_n = tmp - (seq_t)2;
        else                       /* k odd : (-1)^k = -1 -> add 2  */
            a_n = tmp + (seq_t)2;

        a_nm2 = a_nm1;
        a_nm1 = a_n;
    }

    return a_n;
}
